/**
 * The curated problem list.
 *
 * This file is the *hand-maintained* half of the dataset: which problems are in
 * the tracker, what topic and pattern they teach, which curated sheets they
 * belong to, and which companies commonly ask them.
 *
 * The *machine-maintained* half (exact title, LeetCode question number,
 * difficulty, acceptance rate, premium flag) is pulled from LeetCode's public
 * problem list by `scripts/build-problems.ts`, which joins on `slug` and writes
 * `data/problems.json`. That keeps titles/difficulty accurate without anyone
 * re-typing 300 rows by hand.
 *
 * Company tags are indicative — LeetCode's real company data is paywalled and
 * crowd-sourced, so treat them as "commonly reported", not gospel.
 */

export type CuratedProblem = {
  /** LeetCode URL slug — the join key. */
  slug: string;
  /** Primary data structure / subject area. Drives the "by topic" view. */
  topic: Topic;
  /** The reusable technique. Drives the "by pattern" view. */
  pattern: Pattern;
  sheets?: SheetSlug[];
  companies?: string[];
  /** Suggested study order inside its topic (lower = learn first). */
  order?: number;
};

